def build():
    E = []
    def add(id, kind, w, h, prompt, prio): E.append(dict(id=id, kind=kind, w=w, h=h, prompt=prompt, prio=prio))
    for k, d in AYUDANTES.items():
        add(f"ayu-{k}-bust", "bust", 640, 640, f"head and shoulders portrait of {d}, centered, plain warm cream background", 70)
    for k, d in FACCIONES.items():
        add(f"ico-fac-{k}", "icon", 448, 448, f"a heraldic emblem of a faction: {d}, bold symbol, centered", 75)
    for grupo, dic in (("sala", SALAS), ("trampa", TRAMPAS), ("truco", TRUCOS), ("porton", PORTONES), ("hallazgo", HALLAZGOS)):
        for k, d in dic.items():
            add(f"ico-{grupo}-{k}", "icon", 448, 448, f"a game icon of {d}", 80)
    for k, d in BASICAS.items():
        add(f"ico-eq-{k}", "icon", 448, 448, f"a game icon of {d}", 85)
    for i, d in enumerate(MEJUNJES):
        add(f"ico-mejunje-{i+1:02d}", "icon", 448, 448, f"a game icon of an alchemical concoction: {d}, glass flask", 86)
    for i, d in enumerate(ARTILUGIOS):
        add(f"ico-artilugio-{i+1:02d}", "icon", 448, 448, f"a game icon of a goblin gadget: {d}", 87)
    for i, d in enumerate(POCIONES):
        add(f"ico-pocion-{i+1:02d}", "icon", 448, 448, f"a game icon of a magic potion of {d}, glowing bottle", 88)
    for i, d in enumerate(MAGICOS):
        add(f"ico-magico-{i+1:02d}", "icon", 448, 448, f"a game icon of a magic item: {d}", 89)
    return E

if __name__ == "__main__":
    e = build(); print(len(e), "imágenes")
